(()=>{const f=facilities.find(x=>x.id==='moe_0210013');if(!f)return;const source='https://www.city.hachinohe.aomori.jp/section/koiki/seisou/seisou.html';const note='八戸地域広域市町村圏事務組合公式施設概要。第一工場（1992年9月着工・1996年7月竣工、150t/24h×2炉）は設計施工（株）荏原製作所。1980年竣工の第二工場とは区別。';if(!f.builder){f.builder='株式会社荏原製作所';f.builder_source=source;f.builder_scope=note;f.builder_research_status='事務組合公式当初設計施工確認済み';}else{f.builder_additional_research_note=[f.builder_additional_research_note,note].filter(Boolean).join(' ／ ');f.builder_additional_research_urls=[f.builder_additional_research_urls,source].filter(Boolean).join(' | ');}})();